-- Name: trig_prerequisites; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.trig_prerequisites (
    concept_id character varying NOT NULL,
    prerequisite_id character varying NOT NULL
);


--
-- Name: trig_questions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.trig_questions (
    id integer NOT NULL,
    concept_id character varying NOT NULL,
    chapter character varying NOT NULL,
    difficulty double precision,
    title character varying NOT NULL,
    problem_text text NOT NULL,
    created_at timestamp without time zone,
    problem_spec jsonb
);


--
-- Name: trig_questions_id_seq; Type: SEQUENCE; Schema: public; Owner: -
--

CREATE SEQUENCE public.trig_questions_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


