    step_index integer,
    event_type character varying NOT NULL,
    event_payload json,
    "timestamp" timestamp without time zone
);


--
-- Name: trig_telemetry_events_id_seq; Type: SEQUENCE; Schema: public; Owner: -
--

CREATE SEQUENCE public.trig_telemetry_events_id_seq
