    full_name character varying(255) NOT NULL
);


--
-- Name: video_generation_jobs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.video_generation_jobs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
