    question_metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    problem_analysis jsonb,
    solution_steps jsonb,
    verification_result jsonb,
    teaching_sequence jsonb,
    video_spec jsonb,
    status character varying(30) DEFAULT 'PENDING'::character varying NOT NULL,
    review_status character varying(20),
    reviewed_by uuid,
    video_id character varying(200),
    error text,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: video_payloads; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.video_payloads (
