INSERT INTO public.assessments VALUES ('08c456c7-6f3a-4b76-8021-08faaac3cd91', '6a1c22c0-d426-4ba0-927b-b6fe56783ef0', 'bcd51107-f970-4a5e-a0ae-f40c9806ba8e', 'CBSE Class 10 Model Examination: Mathematics', 'Mathematics', 'Class 10', '10-A', 'cbse_80m', 180, 80, 'This question paper contains 38 questions divided into 5 Sections A, B, C, D and E. All questions are compulsory.', '[{"name": "Section A", "type": "mcq", "questions": [{"id": "q-a-1", "text": "If two positive integers a and b are written as a = x^3 y^2 and b = x y^3, where x, y are prime numbers, then HCF(a, b) is:", "bloom": "Understand", "marks": 1, "options": [{"key": "A", "text": "x y", "correct": false}, {"key": "B", "text": "x y^2", "correct": true}, {"key": "C", "text": "x^3 y^3", "correct": false}, {"key": "D", "text": "x^2 y^2", "correct": false}], "difficulty": "Easy"}, {"id": "q-a-2", "text": "The discriminant of the quadratic equation 2x^2 - 4x + 3 = 0 is:", "bloom": "Remember", "marks": 1, "options": [{"key": "A", "text": "-8", "correct": true}, {"key": "B", "text": "10", "correct": false}, {"key": "C", "text": "-16", "correct": false}, {"key": "D", "text": "8", "correct": false}], "difficulty": "Easy"}, {"id": "q-a-3", "text": "If sin theta + cos theta = sqrt(2) cos theta, then (cos theta - sin theta) is equal to:", "bloom": "Apply", "marks": 1, "options": [{"key": "A", "text": "-sqrt(2) cos theta", "correct": false}, {"key": "B", "text": "sqrt(2) sin theta", "correct": true}, {"key": "C", "text": "sqrt(2) cos theta", "correct": false}, {"key": "D", "text": "2 sin theta", "correct": false}], "difficulty": "Medium"}], "section_id": "sec-a", "marks_per_q": 1, "instructions": "Questions 1 to 20 are Multiple Choice Questions carrying 1 mark each."}, {"name": "Section B", "type": "short_answer_1", "questions": [{"id": "q-b-1", "text": "Prove that 3 + 2*sqrt(5) is an irrational number, given that sqrt(5) is irrational.", "bloom": "Understand", "marks": 2, "rubric": "1 mark for assumption and contradiction setup; 1 mark for concluding statement.", "difficulty": "Medium"}, {"id": "q-b-2", "text": "Find the roots of the quadratic equation sqrt(3)x^2 + 10x + 7*sqrt(3) = 0 by factorisation.", "bloom": "Apply", "marks": 2, "rubric": "1 mark for splitting middle term 3x + 7x; 1 mark for correct roots x = -sqrt(3), -7/sqrt(3).", "difficulty": "Medium"}], "section_id": "sec-b", "marks_per_q": 2, "instructions": "Questions 21 to 25 carry 2 marks each with very short answers."}, {"name": "Section C", "type": "short_answer_2", "questions": [{"id": "q-c-1", "text": "Prove that: (sin theta - 2 sin^3 theta) / (2 cos^3 theta - cos theta) = tan theta.", "bloom": "Analyze", "marks": 3, "rubric": "1 mark for taking common terms; 1 mark for identity substitution; 1 mark for simplifying to tan theta.", "difficulty": "Medium"}], "section_id": "sec-c", "marks_per_q": 3, "instructions": "Questions 26 to 31 carry 3 marks each with short answers."}, {"name": "Section D", "type": "long_answer", "questions": [{"id": "q-d-1", "text": "A motor boat whose speed is 18 km/h in still water takes 1 hour more to go 24 km upstream than to return downstream to the same spot. Find the speed of the stream.", "bloom": "Evaluate", "marks": 5, "rubric": "2 marks for formulating equation 24/(18-s) - 24/(18+s) = 1; 2 marks for solving quadratic s^2 + 48s - 324 = 0; 1 mark for s = 6 km/h.", "difficulty": "Hard"}], "section_id": "sec-d", "marks_per_q": 5, "instructions": "Questions 32 to 35 carry 5 marks each with detailed step-by-step working."}, {"name": "Section E", "type": "case_study", "questions": [{"id": "q-e-1", "text": "Case Study: India Gate Shadow Measurement. A student standing 30 m away observes top of monument at 60 deg elevation. Sub-part (i) Find height of monument (2M). Sub-part (ii) Find distance if angle becomes 45 deg (2M).", "bloom": "Create", "marks": 4, "rubric": "2 marks for sub-part (i) h = 30*sqrt(3) m; 2 marks for sub-part (ii) distance = 30*sqrt(3) m.", "difficulty": "Hard"}], "section_id": "sec-e", "marks_per_q": 4, "instructions": "Case study based questions are compulsory. Questions 36 to 38 carry 4 marks each with sub-parts."}]', '2026-09-23', NULL, 'ready', '2026-09-16 19:14:55.333909+05:30', '2026-09-16 19:14:55.333909+05:30');
INSERT INTO public.assessments VALUES ('c300a4d1-b2cb-478a-830a-9801f1b95870', '6a1c22c0-d426-4ba0-927b-b6fe56783ef0', 'bcd51107-f970-4a5e-a0ae-f40c9806ba8e', 'Term 1 Periodic Assessment: Units I & II', 'Mathematics', 'Class 10', '10-A', 'periodic_40m', 90, 40, 'Periodic Test covering Real Numbers, Polynomials, and Quadratic Equations.', '[{"name": "Section A", "type": "mcq", "questions": [{"id": "q-a-1", "text": "If two positive integers a and b are written as a = x^3 y^2 and b = x y^3, where x, y are prime numbers, then HCF(a, b) is:", "bloom": "Understand", "marks": 1, "options": [{"key": "A", "text": "x y", "correct": false}, {"key": "B", "text": "x y^2", "correct": true}, {"key": "C", "text": "x^3 y^3", "correct": false}, {"key": "D", "text": "x^2 y^2", "correct": false}], "difficulty": "Easy"}, {"id": "q-a-2", "text": "The discriminant of the quadratic equation 2x^2 - 4x + 3 = 0 is:", "bloom": "Remember", "marks": 1, "options": [{"key": "A", "text": "-8", "correct": true}, {"key": "B", "text": "10", "correct": false}, {"key": "C", "text": "-16", "correct": false}, {"key": "D", "text": "8", "correct": false}], "difficulty": "Easy"}, {"id": "q-a-3", "text": "If sin theta + cos theta = sqrt(2) cos theta, then (cos theta - sin theta) is equal to:", "bloom": "Apply", "marks": 1, "options": [{"key": "A", "text": "-sqrt(2) cos theta", "correct": false}, {"key": "B", "text": "sqrt(2) sin theta", "correct": true}, {"key": "C", "text": "sqrt(2) cos theta", "correct": false}, {"key": "D", "text": "2 sin theta", "correct": false}], "difficulty": "Medium"}], "section_id": "sec-a", "marks_per_q": 1, "instructions": "Questions 1 to 20 are Multiple Choice Questions carrying 1 mark each."}, {"name": "Section B", "type": "short_answer_1", "questions": [{"id": "q-b-1", "text": "Prove that 3 + 2*sqrt(5) is an irrational number, given that sqrt(5) is irrational.", "bloom": "Understand", "marks": 2, "rubric": "1 mark for assumption and contradiction setup; 1 mark for concluding statement.", "difficulty": "Medium"}, {"id": "q-b-2", "text": "Find the roots of the quadratic equation sqrt(3)x^2 + 10x + 7*sqrt(3) = 0 by factorisation.", "bloom": "Apply", "marks": 2, "rubric": "1 mark for splitting middle term 3x + 7x; 1 mark for correct roots x = -sqrt(3), -7/sqrt(3).", "difficulty": "Medium"}], "section_id": "sec-b", "marks_per_q": 2, "instructions": "Questions 21 to 25 carry 2 marks each with very short answers."}, {"name": "Section C", "type": "short_answer_2", "questions": [{"id": "q-c-1", "text": "Prove that: (sin theta - 2 sin^3 theta) / (2 cos^3 theta - cos theta) = tan theta.", "bloom": "Analyze", "marks": 3, "rubric": "1 mark for taking common terms; 1 mark for identity substitution; 1 mark for simplifying to tan theta.", "difficulty": "Medium"}], "section_id": "sec-c", "marks_per_q": 3, "instructions": "Questions 26 to 31 carry 3 marks each with short answers."}]', '2026-09-28', '7d39e53e-9ad3-472d-a987-b5141c99bfce', 'scheduled', '2026-09-16 19:14:55.333909+05:30', '2026-09-16 19:14:55.333909+05:30');
