INSERT INTO public.coordgeo_concepts VALUES ('coordgeo-c1', 'Cartesian Basics', 'Coordinate Geometry', 1, 'Abscissa (x), ordinate (y), origin (0,0), plotting P(x,y), and identifying quadrants.', 'Point = (abscissa, ordinate) = (x, y)', '{}');
INSERT INTO public.coordgeo_concepts VALUES ('coordgeo-c2', 'Distance Formula Between Two Points', 'Coordinate Geometry', 1.2, 'Distance between P(x1,y1) and Q(x2,y2), derived from the Pythagorean theorem.', 'PQ = sqrt((x2-x1)^2 + (y2-y1)^2)', '{}');
INSERT INTO public.coordgeo_concepts VALUES ('coordgeo-c3', 'Distance From Origin', 'Coordinate Geometry', 1.2, 'Special case of the distance formula where one point is the origin (0,0).', 'OP = sqrt(x^2 + y^2)', '{}');
INSERT INTO public.coordgeo_concepts VALUES ('coordgeo-c4', 'Collinearity of Points (using Distance)', 'Coordinate Geometry', 1.6, 'Using distance to prove three points are collinear: AB + BC = AC.', 'Collinear if AB + BC = AC', '{}');
INSERT INTO public.coordgeo_concepts VALUES ('coordgeo-c5', 'Verifying Triangle Types (using Distance)', 'Coordinate Geometry', 1.6, 'Using distance to verify equilateral, isosceles, or right-angled triangles.', 'Right angle if a^2 + b^2 = c^2 (Pythagoras converse)', '{}');
INSERT INTO public.coordgeo_concepts VALUES ('coordgeo-c6', 'Verifying Quadrilateral Types (using Distance)', 'Coordinate Geometry', 1.7, 'Using distance to verify square, rhombus, or parallelogram properties (sides and diagonals).', 'Square: all sides equal AND both diagonals equal', '{}');
INSERT INTO public.coordgeo_concepts VALUES ('coordgeo-c7', 'Section Formula - Internal Division', 'Coordinate Geometry', 1.8, 'Point P(x,y) dividing A(x1,y1) and B(x2,y2) internally in ratio m1:m2.', 'x = (m1*x2+m2*x1)/(m1+m2), y = (m1*y2+m2*y1)/(m1+m2)', '{}');
INSERT INTO public.coordgeo_concepts VALUES ('coordgeo-c8', 'Midpoint Formula', 'Coordinate Geometry', 1.4, 'Special case of the section formula where the ratio is 1:1.', 'M = ((x1+x2)/2, (y1+y2)/2)', '{}');
INSERT INTO public.coordgeo_concepts VALUES ('coordgeo-c9', 'Finding Ratio / Axis Division', 'Coordinate Geometry', 2, 'Inverse of the section formula: given the dividing point, find the ratio k:1. On the y-axis x=0; on the x-axis y=0.', 'Set x=0 (or y=0) in the section formula and solve for k', '{}');
INSERT INTO public.coordgeo_concepts VALUES ('coordgeo-c10', 'Division into Equal Parts - Trisection', 'Coordinate Geometry', 2.2, 'Dividing AB into 3 equal parts: P divides 1:2, Q divides 2:1 (Q is also the midpoint of PB).', 'P=((x2+2x1)/3,(y2+2y1)/3), Q=((2x2+x1)/3,(2y2+y1)/3)', '{}');
INSERT INTO public.coordgeo_concepts VALUES ('coordgeo-c11', 'Parallelogram Diagonal Property', 'Coordinate Geometry', 1.9, 'Diagonals of a parallelogram bisect each other: midpoint of AC = midpoint of BD.', '(x1+x3)/2 = (x2+x4)/2, and the same for y', '{}');
INSERT INTO public.coordgeo_concepts VALUES ('coordgeo-c12', 'Advanced Area Application - Rhombus', 'Coordinate Geometry', 2.4, 'Combining distance and midpoint to find area: Area of a rhombus = 1/2 * product of diagonals.', 'Area = 1/2 * d1 * d2', '{}');
