INSERT INTO public.coordgeo_questions VALUES (1, 'coordgeo-c1', 'Coordinate Geometry', 1, 'Quadrant Identification', 'If the abscissa of a point is 4 and ordinate is -5, write the point. In which quadrant does it lie?', '{"high": "Abscissa = x, Ordinate = y. Quadrant IV is (+, -).", "mid": "Point = (abscissa, ordinate).", "low": "x > 0, y < 0 -- which quadrant?"}', '["Point = (abscissa, ordinate) = (4, -5)", "x > 0, y < 0 => 4th quadrant"]', '(4, -5), Quadrant IV', '{"problem_type": "COORDGEO_CARTESIAN_BASICS", "abscissa": 4, "ordinate": -5}', '2026-09-17 21:16:11.155233');
INSERT INTO public.coordgeo_questions VALUES (2, 'coordgeo-c2', 'Coordinate Geometry', 1.2, 'NCERT Ex 7.1 Q1', 'Find the distance between A(2,3) and B(4,1).', '{"high": "Use sqrt[(x2-x1)^2+(y2-y1)^2]. Watch the sign.", "mid": "Subtract x''s and y''s, square, add, root.", "low": "AB = sqrt[(4-2)^2 + (1-3)^2]"}', '["x2-x1 = 2, y2-y1 = -2", "AB = sqrt[2^2 + (-2)^2] = sqrt(8) = 2*sqrt(2)"]', '2*sqrt(2) units', '{"problem_type": "COORDGEO_DISTANCE", "p1": ["2", "3"], "p2": ["4", "1"]}', '2026-09-17 21:16:11.155233');
INSERT INTO public.coordgeo_questions VALUES (3, 'coordgeo-c3', 'Coordinate Geometry', 1.2, 'NCERT Ex 7.1 Q2', 'Find the distance of point P(-6,8) from the origin.', '{"high": "Origin is (0,0). Use sqrt(x^2+y^2).", "mid": "OP = sqrt[(-6)^2 + 8^2]", "low": "Square both coordinates and add, then root."}', '["OP = sqrt[(-6-0)^2 + (8-0)^2] = sqrt(36+64) = sqrt(100)"]', '10 units', '{"problem_type": "COORDGEO_DISTANCE_FROM_ORIGIN", "p": ["-6", "8"]}', '2026-09-17 21:16:11.155233');
INSERT INTO public.coordgeo_questions VALUES (4, 'coordgeo-c4', 'Coordinate Geometry', 1.6, 'NCERT Ex 7.1 Q3 (verified set)', 'Check if A(1,-1), B(5,2), C(9,5) are collinear.', '{"high": "Find AB, BC, AC. If AB+BC=AC, the points are collinear.", "mid": "Use the distance formula for all three pairs.", "low": "Compare the sum of the two smaller distances to the largest."}', '["AB = sqrt(4^2+3^2) = 5", "BC = sqrt(4^2+3^2) = 5", "AC = sqrt(8^2+6^2) = 10", "AB+BC = 5+5 = 10 = AC => Collinear"]', 'Collinear', '{"problem_type": "COORDGEO_COLLINEARITY", "p1": ["1", "-1"], "p2": ["5", "2"], "p3": ["9", "5"]}', '2026-09-17 21:16:11.155233');
INSERT INTO public.coordgeo_questions VALUES (5, 'coordgeo-c5', 'Coordinate Geometry', 1.6, 'Right Triangle Verification', 'Prove that A(2,-2), B(14,10), C(11,13) forms a right triangle.', '{"high": "Find AB^2, BC^2, AC^2. Check if the Pythagoras converse holds.", "mid": "Use the distance formula for all three sides.", "low": "Which side is the longest? Check a^2+b^2=c^2."}', '["AB^2 = 12^2+12^2 = 288", "BC^2 = 3^2+3^2 = 18", "AC^2 = 9^2+15^2 = 306", "AB^2+BC^2 = 288+18 = 306 = AC^2 => right angle at B"]', 'Right triangle, right angle at B', '{"problem_type": "COORDGEO_TRIANGLE_TYPE", "p1": ["2", "-2"], "p2": ["14", "10"], "p3": ["11", "13"]}', '2026-09-17 21:16:11.155233');
INSERT INTO public.coordgeo_questions VALUES (6, 'coordgeo-c6', 'Coordinate Geometry', 1.7, 'Square Verification', 'Show that points (-1,-2),(1,0),(-1,2),(-3,0) form a square.', '{"high": "Check all four sides are equal AND both diagonals are equal.", "mid": "Find AB, BC, CD, DA and both diagonals.", "low": "Use the distance formula for each side and diagonal."}', '["AB=BC=CD=DA=sqrt(8) => all sides equal", "Diagonal AC = 4, BD = 4 => diagonals equal", "All sides equal + diagonals equal => Square"]', 'Square', '{"problem_type": "COORDGEO_QUADRILATERAL_TYPE", "p1": ["-1", "-2"], "p2": ["1", "0"], "p3": ["-1", "2"], "p4": ["-3", "0"]}', '2026-09-17 21:16:11.155233');
INSERT INTO public.coordgeo_questions VALUES (7, 'coordgeo-c7', 'Coordinate Geometry', 1.8, 'NCERT Ex 7.2 Q1', 'Find the point P which divides the line segment joining A(1,-5) and B(-4,5) in the ratio 1:2.', '{"high": "Use x=(m1*x2+m2*x1)/(m1+m2) and the same form for y.", "mid": "m1=1, m2=2.", "low": "Substitute into the section formula."}', '["x = (1*(-4)+2*1)/3 = -2/3", "y = (1*5+2*(-5))/3 = -5/3"]', '(-2/3, -5/3)', '{"problem_type": "COORDGEO_SECTION_FORMULA", "p1": ["1", "-5"], "p2": ["-4", "5"], "m1": 1, "m2": 2}', '2026-09-17 21:16:11.155233');
INSERT INTO public.coordgeo_questions VALUES (8, 'coordgeo-c8', 'Coordinate Geometry', 1.4, 'NCERT Ex 7.2 Q7', 'Find the midpoint of A(2,-3) and B(-6,3).', '{"high": "M = ((x1+x2)/2, (y1+y2)/2).", "mid": "Add the x''s, divide by 2; add the y''s, divide by 2.", "low": "Average the two x-coordinates and the two y-coordinates."}', '["x = (2+(-6))/2 = -2", "y = (-3+3)/2 = 0"]', '(-2, 0)', '{"problem_type": "COORDGEO_MIDPOINT", "p1": ["2", "-3"], "p2": ["-6", "3"]}', '2026-09-17 21:16:11.155233');
INSERT INTO public.coordgeo_questions VALUES (9, 'coordgeo-c9', 'Coordinate Geometry', 2, 'NCERT Ex 7.2 Q9', 'Find the ratio in which the y-axis divides the line joining P(-4,2) and Q(8,6). Also find the point of intersection.', '{"high": "On the y-axis, x=0. Set the section-formula x-expression to 0 and solve for k.", "mid": "Let the ratio be k:1.", "low": "x = (k*8 + 1*(-4))/(k+1) = 0"}', '["8k - 4 = 0 => k = 1/2 => ratio 1:2", "y = ((1/2)*6 + 2)/(3/2) = 10/3"]', 'Ratio 1:2, point (0, 10/3)', '{"problem_type": "COORDGEO_RATIO_AXIS_DIVISION", "p1": ["-4", "2"], "p2": ["8", "6"], "axis": "y"}', '2026-09-17 21:16:11.155233');
INSERT INTO public.coordgeo_questions VALUES (10, 'coordgeo-c10', 'Coordinate Geometry', 2.2, 'NCERT Ex 7.2 Q4', 'Find the trisection points of A(4,-1) and B(-2,-3).', '{"high": "P divides 1:2, Q divides 2:1.", "mid": "Apply the section formula twice.", "low": "Q is also the midpoint of P and B."}', '["P = ((-2+8)/3, (-3-2)/3) = (2, -5/3)", "Q = ((-4+4)/3, (-6-1)/3) = (0, -7/3)"]', 'P(2, -5/3), Q(0, -7/3)', '{"problem_type": "COORDGEO_TRISECTION", "p1": ["4", "-1"], "p2": ["-2", "-3"]}', '2026-09-17 21:16:11.155233');
INSERT INTO public.coordgeo_questions VALUES (11, 'coordgeo-c11', 'Coordinate Geometry', 1.9, 'NCERT Ex 7.2 Q10', 'If A(6,1), B(8,2), C(9,4), D(p,3) are vertices of a parallelogram ABCD, find p.', '{"high": "Midpoint of AC = midpoint of BD.", "mid": "Set up the midpoint of each diagonal.", "low": "Equate the x-coordinates of both midpoints."}', '["Mid AC = (7.5, 2.5)", "Mid BD = ((8+p)/2, 2.5)", "7.5 = (8+p)/2 => p = 7"]', 'p = 7', '{"problem_type": "COORDGEO_PARALLELOGRAM_VERTEX", "known": {"A": ["6", "1"], "B": ["8", "2"], "C": ["9", "4"]}, "missing_label": "D"}', '2026-09-17 21:16:11.155233');
INSERT INTO public.coordgeo_questions VALUES (12, 'coordgeo-c12', 'Coordinate Geometry', 2.4, 'Board 2020 Rhombus Area', 'Find the area of a rhombus whose vertices are (3,0),(4,5),(-1,4),(-2,-1), taken in order.', '{"high": "Area = 1/2 * d1 * d2. Find both diagonals using the distance formula.", "mid": "The diagonals connect opposite vertices.", "low": "d1 = distance between vertex 1 and 3; d2 = distance between vertex 2 and 4."}', '["d1 = AC = sqrt(16+16) = 4*sqrt(2)", "d2 = BD = sqrt(36+36) = 6*sqrt(2)", "Area = 1/2 * 4*sqrt(2) * 6*sqrt(2) = 24"]', '24 sq units', '{"problem_type": "COORDGEO_DIAGONAL_AREA", "p1": ["3", "0"], "p2": ["4", "5"], "p3": ["-1", "4"], "p4": ["-2", "-1"]}', '2026-09-17 21:16:11.155233');
