INSERT INTO public.student_mistakes VALUES ('ab33298c-5f4c-4519-903a-e8fd471aa1b3', '499eff2a-78ca-42d2-97dd-6abcdf187638', '737231f7-d5fe-424c-aff7-ce491100dea4', 'Quadratic Equations', 'Quadratic Formula & Nature of Roots', 'Find the roots of 2x^2 - 7x + 3 = 0 using the quadratic formula.', 'x = 2, 1/3', 'x = 3, 1/2', 'Using x = (-b +- sqrt(b^2 - 4ac)) / (2a): b^2 - 4ac = 49 - 24 = 25. Thus x = (7 +- 5) / 4 => x = 3 or x = 1/2.', 'needs_practice', '2026-09-16 23:18:56.107626+05:30');
INSERT INTO public.student_mistakes VALUES ('b27c08c6-356f-4f74-bd07-f9d9d0f1a291', '499eff2a-78ca-42d2-97dd-6abcdf187638', '737231f7-d5fe-424c-aff7-ce491100dea4', 'Light — Reflection and Refraction', 'Mirror Formula and Sign Conventions', 'A convex mirror with focal length 15 cm forms an image 10 cm behind the mirror. What is the object distance?', 'u = -20 cm', 'u = -30 cm', 'Mirror formula: 1/f = 1/v + 1/u. For convex mirror, f = +15 cm, v = +10 cm. 1/u = 1/15 - 1/10 = -1/30. So u = -30 cm.', 'needs_practice', '2026-09-16 23:18:56.107626+05:30');
INSERT INTO public.student_mistakes VALUES ('aa2131ab-346d-4fef-98f2-d2783f134793', '499eff2a-78ca-42d2-97dd-6abcdf187638', '737231f7-d5fe-424c-aff7-ce491100dea4', 'Introduction to Trigonometry', 'Trigonometric Ratios of Specific Angles', 'Evaluate: (sin 30° + tan 45° - cosec 60°) / (sec 30° + cos 60° + cot 45°).', '1', '(43 - 24√3) / 11', 'Substitute sin 30° = 1/2, tan 45° = 1, cosec 60° = 2/√3, sec 30° = 2/√3, cos 60° = 1/2, cot 45° = 1, and rationalize the denominator.', 'needs_practice', '2026-09-16 23:18:56.107626+05:30');
