INSERT INTO public.student_mistakes VALUES ('2a0d0535-483d-45b2-b19c-b99fce87e39f', '33cde123-5dc4-406c-80cf-902c10a30130', '05c6d79a-6855-4db8-b1f6-822ea52980d0', 'Light — Reflection and Refraction', 'Mirror Formula and Sign Conventions', 'A convex mirror with focal length 15 cm forms an image 10 cm behind the mirror. What is the object distance?', 'u = -20 cm', 'u = -30 cm', 'Mirror formula: 1/f = 1/v + 1/u. For convex mirror, f = +15 cm, v = +10 cm. 1/u = 1/15 - 1/10 = -1/30. So u = -30 cm.', 'needs_practice', '2026-09-16 23:18:56.107626+05:30');
INSERT INTO public.student_mistakes VALUES ('609c7ca3-8058-4a29-a075-95342f038cfe', '33cde123-5dc4-406c-80cf-902c10a30130', '05c6d79a-6855-4db8-b1f6-822ea52980d0', 'Introduction to Trigonometry', 'Trigonometric Ratios of Specific Angles', 'Evaluate: (sin 30° + tan 45° - cosec 60°) / (sec 30° + cos 60° + cot 45°).', '1', '(43 - 24√3) / 11', 'Substitute sin 30° = 1/2, tan 45° = 1, cosec 60° = 2/√3, sec 30° = 2/√3, cos 60° = 1/2, cot 45° = 1, and rationalize the denominator.', 'needs_practice', '2026-09-16 23:18:56.107626+05:30');
INSERT INTO public.student_mistakes VALUES ('8c2bba95-6045-47dc-9af9-25dc444b9ec4', '9247d818-b236-447e-8c1c-e82c78b2b3a7', '962021d6-227f-4f14-aabb-37d83c94a858', 'Quadratic Equations', 'Quadratic Formula & Nature of Roots', 'Find the roots of 2x^2 - 7x + 3 = 0 using the quadratic formula.', 'x = 2, 1/3', 'x = 3, 1/2', 'Using x = (-b +- sqrt(b^2 - 4ac)) / (2a): b^2 - 4ac = 49 - 24 = 25. Thus x = (7 +- 5) / 4 => x = 3 or x = 1/2.', 'needs_practice', '2026-09-16 23:18:56.107626+05:30');
