INSERT INTO public.student_mistakes VALUES ('e929a3b6-95a5-49d7-be57-8a63bec96a9c', 'e75291f5-7558-4d40-aa97-9e7a94cacf7f', '0719090b-783a-4fe1-9125-aaa0ebcbb5cc', 'Light — Reflection and Refraction', 'Mirror Formula and Sign Conventions', 'A convex mirror with focal length 15 cm forms an image 10 cm behind the mirror. What is the object distance?', 'u = -20 cm', 'u = -30 cm', 'Mirror formula: 1/f = 1/v + 1/u. For convex mirror, f = +15 cm, v = +10 cm. 1/u = 1/15 - 1/10 = -1/30. So u = -30 cm.', 'needs_practice', '2026-09-16 23:18:56.107626+05:30');
INSERT INTO public.student_mistakes VALUES ('d1ef55ac-dd5e-415b-8fc1-5166d257a63a', 'e75291f5-7558-4d40-aa97-9e7a94cacf7f', '0719090b-783a-4fe1-9125-aaa0ebcbb5cc', 'Introduction to Trigonometry', 'Trigonometric Ratios of Specific Angles', 'Evaluate: (sin 30° + tan 45° - cosec 60°) / (sec 30° + cos 60° + cot 45°).', '1', '(43 - 24√3) / 11', 'Substitute sin 30° = 1/2, tan 45° = 1, cosec 60° = 2/√3, sec 30° = 2/√3, cos 60° = 1/2, cot 45° = 1, and rationalize the denominator.', 'needs_practice', '2026-09-16 23:18:56.107626+05:30');
INSERT INTO public.student_mistakes VALUES ('5ca529ca-f2f5-4d79-b861-559534fa65c6', 'e75291f5-7558-4d40-aa97-9e7a94cacf7f', '0855cad4-a2d3-4d90-85ba-d5b46dff58d7', 'Quadratic Equations', 'Quadratic Formula & Nature of Roots', 'Find the roots of 2x^2 - 7x + 3 = 0 using the quadratic formula.', 'x = 2, 1/3', 'x = 3, 1/2', 'Using x = (-b +- sqrt(b^2 - 4ac)) / (2a): b^2 - 4ac = 49 - 24 = 25. Thus x = (7 +- 5) / 4 => x = 3 or x = 1/2.', 'needs_practice', '2026-09-16 23:18:56.107626+05:30');
INSERT INTO public.student_mistakes VALUES ('5944d351-ece8-4a92-8b99-fc96b5f77391', 'e75291f5-7558-4d40-aa97-9e7a94cacf7f', '0855cad4-a2d3-4d90-85ba-d5b46dff58d7', 'Light — Reflection and Refraction', 'Mirror Formula and Sign Conventions', 'A convex mirror with focal length 15 cm forms an image 10 cm behind the mirror. What is the object distance?', 'u = -20 cm', 'u = -30 cm', 'Mirror formula: 1/f = 1/v + 1/u. For convex mirror, f = +15 cm, v = +10 cm. 1/u = 1/15 - 1/10 = -1/30. So u = -30 cm.', 'needs_practice', '2026-09-16 23:18:56.107626+05:30');
