INSERT INTO public.student_mistakes VALUES ('2b1dc87f-afde-4ba7-a566-91247969655a', '457f9d5b-dd87-4d29-be1f-6188757bb332', '58f288bc-a765-4ed6-b11e-531e8e894760', 'Light — Reflection and Refraction', 'Mirror Formula and Sign Conventions', 'A convex mirror with focal length 15 cm forms an image 10 cm behind the mirror. What is the object distance?', 'u = -20 cm', 'u = -30 cm', 'Mirror formula: 1/f = 1/v + 1/u. For convex mirror, f = +15 cm, v = +10 cm. 1/u = 1/15 - 1/10 = -1/30. So u = -30 cm.', 'needs_practice', '2026-09-16 23:18:56.107626+05:30');
