INSERT INTO public.student_wiki_notes VALUES ('b2c35c4f-1a2a-4eea-9499-a4e37648c4b3', '499eff2a-78ca-42d2-97dd-6abcdf187638', '737231f7-d5fe-424c-aff7-ce491100dea4', 'Real Numbers', 'Fundamental Theorem of Arithmetic', 'quote', 'Fundamental Theorem of Arithmetic: Every composite number can be expressed (factorised) as a product of primes, and this factorisation is unique, apart from the order in which the prime factors occur.', '2026-09-16 23:18:56.107626+05:30');
