INSERT INTO public.trig_questions VALUES (1, 'trig-101', 'Introduction to Trigonometry', 1, 'NCERT Ex 8.1 Q1 (24, 7)', 'In triangle ABC right angled at B, AB = 24 cm, BC = 7 cm. Determine: (i) sin A, cos A', '2026-09-13 13:25:23.635709', '{"side_sum": null, "vertices": ["A", "B", "C"], "known_sides": {"AB": "24", "BC": "7"}, "problem_type": "RIGHT_TRIANGLE_RATIOS", "target_ratios": [["sin", "A"], ["cos", "A"]], "right_angle_vertex": "B"}');
INSERT INTO public.trig_questions VALUES (2, 'trig-101', 'Introduction to Trigonometry', 1, 'Pythagorean Triplet (5, 12)', 'In triangle ABC right angled at B, AB = 5 cm, BC = 12 cm. Determine: (i) sin A, cos A', '2026-09-13 13:25:23.635709', '{"side_sum": null, "vertices": ["A", "B", "C"], "known_sides": {"AB": "5", "BC": "12"}, "problem_type": "RIGHT_TRIANGLE_RATIOS", "target_ratios": [["sin", "A"], ["cos", "A"]], "right_angle_vertex": "B"}');
INSERT INTO public.trig_questions VALUES (3, 'trig-102', 'Introduction to Trigonometry', 1.5, 'NCERT Ex 8.1 Q3 (3, 4)', 'In triangle ABC right angled at B, AB = 3 cm, BC = 4 cm. Determine: (i) sin A, cos A', '2026-09-13 13:25:23.635709', '{"side_sum": null, "vertices": ["A", "B", "C"], "known_sides": {"AB": "3", "BC": "4"}, "problem_type": "RIGHT_TRIANGLE_RATIOS", "target_ratios": [["sin", "A"], ["cos", "A"]], "right_angle_vertex": "B"}');
INSERT INTO public.trig_questions VALUES (4, 'trig-102', 'Introduction to Trigonometry', 1.5, 'Given tan A, evaluate sin A', 'If tan A = 4/3, evaluate sin A', '2026-09-13 13:25:23.635709', '{"expr": "SINA", "angle_var": "A", "given_func": "tan", "given_coeff": "1", "given_value": "4/3", "problem_type": "TRIG_RATIO_EVALUATION"}');
INSERT INTO public.trig_questions VALUES (5, 'trig-103', 'Introduction to Trigonometry', 1.8, 'NCERT Ex 8.1 Reciprocal Ratios', 'In triangle ABC right angled at B, AB = 12 cm, BC = 5 cm. Determine: (i) sec A, cot A', '2026-09-13 13:25:23.635709', '{"side_sum": null, "vertices": ["A", "B", "C"], "known_sides": {"AB": "12", "BC": "5"}, "problem_type": "RIGHT_TRIANGLE_RATIOS", "target_ratios": [["sec", "A"], ["cot", "A"]], "right_angle_vertex": "B"}');
INSERT INTO public.trig_questions VALUES (6, 'trig-103', 'Introduction to Trigonometry', 2, 'NCERT Ex 8.1 Q8 Evaluation', 'If 3 cot A = 4, evaluate (1 - tan^2 A) / (1 + tan^2 A)', '2026-09-13 13:25:23.635709', '{"expr": "(1 - TANA**2) / (1 + TANA**2)", "angle_var": "A", "given_func": "cot", "given_coeff": "3", "given_value": "4", "problem_type": "TRIG_RATIO_EVALUATION"}');
INSERT INTO public.trig_questions VALUES (7, 'trig-104', 'Introduction to Trigonometry', 2.2, 'NCERT Ex 8.4 Q1 (in terms of cot A)', 'Express sin A, sec A and tan A in terms of cot A', '2026-09-13 13:25:23.635709', '{"variable": "A", "base_func": "cot", "problem_type": "EXPRESS_RATIOS_IN_TERMS_OF", "target_funcs": ["sin", "sec", "tan"]}');
INSERT INTO public.trig_questions VALUES (8, 'trig-104', 'Introduction to Trigonometry', 2.2, 'Express ratios in terms of sin A', 'Express cos A, tan A and sec A in terms of sin A', '2026-09-13 13:25:23.635709', '{"variable": "A", "base_func": "sin", "problem_type": "EXPRESS_RATIOS_IN_TERMS_OF", "target_funcs": ["cos", "tan", "sec"]}');
INSERT INTO public.trig_questions VALUES (9, 'trig-105', 'Introduction to Trigonometry', 2, 'NCERT Ex 8.2 Q1 Compound Evaluation', 'Evaluate: 2 tan^2 45 + cos^2 30 - sin^2 60', '2026-09-13 13:25:23.635709', '{"expression": "2*tan(45)**2 + cos(30)**2 - sin(60)**2", "problem_type": "COMPOUND_EVALUATION"}');
INSERT INTO public.trig_questions VALUES (10, 'trig-105', 'Introduction to Trigonometry', 2.5, 'NCERT Ex 8.2 Q3 Angle System', 'If tan (A + B) = sqrt(3) and tan (A - B) = 1/sqrt(3), find A and B.', '2026-09-13 13:25:23.635709', '{"eq1_arg": "A + B", "eq1_val": "sqrt(3)", "eq2_arg": "A - B", "eq2_val": "1/sqrt(3)", "eq1_func": "tan", "eq2_func": "tan", "problem_type": "ANGLE_SYSTEM"}');
INSERT INTO public.trig_questions VALUES (11, 'trig-106', 'Trigonometric Identities', 2.5, 'Conditional Identity (sin + cos = sqrt 3)', 'If sin A + cos A = sqrt(3), prove that tan A + cot A = 1', '2026-09-13 13:25:23.635709', '{"variable": "A", "given_value": "sqrt(3)", "problem_type": "CONDITIONAL_TRIG_IDENTITY", "target_value": "1"}');
INSERT INTO public.trig_questions VALUES (12, 'trig-106', 'Trigonometric Identities', 2.5, 'Reciprocal Conjugate Identity (7)', 'If sec A + tan A = 7, compute sec A - tan A', '2026-09-13 13:25:23.635709', '{"func1": "sec", "func2": "tan", "variable": "A", "given_sign": "+", "given_value": "7", "target_sign": "-", "problem_type": "RECIPROCAL_CONJUGATE_IDENTITY"}');
INSERT INTO public.trig_questions VALUES (13, 'trig-107', 'Trigonometric Identities', 2.8, 'Reciprocal Conjugate sec/tan (5)', 'If sec A + tan A = 5, compute sec A - tan A', '2026-09-13 13:25:23.635709', '{"func1": "sec", "func2": "tan", "variable": "A", "given_sign": "+", "given_value": "5", "target_sign": "-", "problem_type": "RECIPROCAL_CONJUGATE_IDENTITY"}');
INSERT INTO public.trig_questions VALUES (14, 'trig-107', 'Trigonometric Identities', 2.8, 'Reciprocal Conjugate csc/cot (3)', 'If csc A + cot A = 3, compute csc A - cot A', '2026-09-13 13:25:23.635709', '{"func1": "csc", "func2": "cot", "variable": "A", "given_sign": "+", "given_value": "3", "target_sign": "-", "problem_type": "RECIPROCAL_CONJUGATE_IDENTITY"}');
INSERT INTO public.trig_questions VALUES (15, 'trig-108', 'Trigonometric Identities', 3.2, 'NCERT Ex 8.4 Q5 (viii) Proof', 'Prove that (sin A + csc A)^2 + (cos A + sec A)^2 = 7 + tan^2 A + cot^2 A', '2026-09-13 13:25:23.635709', '{"lhs_text": "(sin(A) + csc(A))**2 + (cos(A) + sec(A))**2", "rhs_text": "7 + tan(A)**2 + cot(A)**2", "variable": "A", "problem_type": "TRIG_IDENTITY_PROOF"}');
INSERT INTO public.trig_questions VALUES (16, 'trig-108', 'Trigonometric Identities', 3, 'NCERT Ex 8.4 Q5 (x) Proof', 'Prove that (1 + tan^2 A) / (1 + cot^2 A) = tan^2 A', '2026-09-13 13:25:23.635709', '{"lhs_text": "(1 + tan(A)**2)/(1 + cot(A)**2)", "rhs_text": "tan(A)**2", "variable": "A", "problem_type": "TRIG_IDENTITY_PROOF"}');
INSERT INTO public.trig_questions VALUES (17, 'trig-109', 'Some Applications of Trigonometry', 2.5, 'NCERT Ex 9.1 Q1 Tower Elevation', 'A tower stands vertically on the ground. From a point on the ground, which is 15 m away from the foot of the tower, the angle of elevation of the top of the tower is found to be 60 degrees. Find the height of the tower.', '2026-09-13 13:25:23.635709', '{"target": "height", "angle_val": 60, "archetype": "SINGLE", "distance_val": "15", "problem_type": "HEIGHTS_AND_DISTANCES", "vertical_entity": "tower", "horizontal_entity": "ground"}');
INSERT INTO public.trig_questions VALUES (18, 'trig-109', 'Some Applications of Trigonometry', 2.5, 'Oswaal Shadow Altitude', 'A tower AB is 20 m high and BC, its shadow on the ground, is 20 sqrt(3) m long. Find the Sun''s altitude.', '2026-09-13 13:25:23.635709', '{"target": "angle", "archetype": "SINGLE", "height_val": "20", "distance_val": "20*sqrt(3)", "problem_type": "HEIGHTS_AND_DISTANCES", "vertical_entity": "tower", "horizontal_entity": "ground"}');
INSERT INTO public.trig_questions VALUES (19, 'trig-110', 'Some Applications of Trigonometry', 3.5, 'NCERT Ex 9.1 Bridge River Width', 'From a point on a bridge across a river, the angles of depression of the banks on opposite sides of the river are 30 degrees and 45 degrees. If the bridge is at a height of 3 m from the banks, find the width of the river.', '2026-09-13 13:25:23.635709', '{"theta1": 30, "theta2": 45, "measure": "3", "archetype": "CROSS", "problem_type": "HEIGHTS_AND_DISTANCES", "vertical_entity": "bridge", "horizontal_entity": "river"}');
INSERT INTO public.trig_questions VALUES (20, 'trig-110', 'Some Applications of Trigonometry', 3.5, 'NCERT Ex 9.1 Two Equal Poles', 'Two poles of equal heights are standing opposite each other on either side of the road, which is 80 m wide. From a point between them on the road, the angles of elevation of the tops of the poles are 60 degrees and 30 degrees. Find the height of the poles.', '2026-09-13 13:25:23.635709', '{"theta1": 60, "theta2": 30, "measure": "80", "archetype": "EQUAL_POLES", "problem_type": "HEIGHTS_AND_DISTANCES", "vertical_entity": "poles", "horizontal_entity": "road"}');
